"""Accessible, self-contained editorial report. Generated from verified aggregates."""
import html
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
BOTS = ('maia1','maia5','maia9')
COLORS = ['#b7e281','#e8b96b','#b9aceb']
def esc(v): return html.escape(str(v))
def n(v): return f'{v:,}'
def pct(v,d): return f'{100*v/d:.1f}%' if d else '—'
def label(b): return b.replace('maia','Maia ')
def table(headers, rows):
    return '<div class="table-scroll"><table><thead><tr>'+''.join(f'<th scope="col">{esc(x)}</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(f'<td>{esc(x)}</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def bars(items, denominator, color='var(--green)'):
    maximum=max(v for _,v in items)
    return ''.join(f'<div class="bar-row"><span>{esc(k)}</span><b>{pct(v,denominator)}</b><div class="track"><i style="width:{100*v/maximum:.2f}%;background:{color}"></i></div><small>{n(v)} games</small></div>' for k,v in items)
def month_chart(r):
    months=r['monthly_complete']; W,H,L,T,P=1000,300,48,20,235; step=930/len(months); ceiling=80000
    out=[f'<svg viewBox="0 0 {W} {H}" role="img" aria-labelledby="month-title month-desc"><title id="month-title">Monthly rated Maia games</title><desc id="month-desc">Stacked bars from November 2023 through September 2026. Peak: May 2026, 70,936 games. Full values are in the table below.</desc>']
    for v in range(0,80001,20000):
        y=T+P-v/ceiling*P
        out.append(f'<path d="M{L} {y}H990" stroke="#dddcd1"/><text x="{L-9}" y="{y+4}" text-anchor="end">{v//1000}k</text>')
    for j,m in enumerate(months):
        y=T+P
        for b,c in zip(BOTS,COLORS):
            h=m['per_bot'][b]/ceiling*P;y-=h
            out.append(f'<rect x="{L+j*step+4:.2f}" y="{y:.2f}" width="{step-7:.2f}" height="{h:.2f}" fill="{c}"><title>{m["month"]} · {label(b)}: {n(m["per_bot"][b])}</title></rect>')
        if j in [0,8,14,20,26,34]:
            out.append(f'<text x="{L+j*step+step/2:.2f}" y="280" text-anchor="middle">{m["month"]}</text>')
    return ''.join(out)+'</svg>'

def render(s, insights):
    r=s['rated_three_years']; a=s['all_time']; accounts=r['accounts']; total=r['unique_games']
    first=r['first_12_complete_months']['games']; last=r['last_12_complete_months']['games']; growth=(last/first-1)*100
    botcards=''.join(f'<article class="bot-card"><div class="bot-top"><span class="piece" aria-hidden="true">{p}</span><span class="chip">{label(b)}</span></div><strong>{n(r["per_bot"][b])}</strong><p>rated games · {pct(r["per_bot"][b],total)} of this collection</p><div class="mini-track"><i style="width:{100*r["per_bot"][b]/total}%;background:{c}"></i></div><p class="small">Median opponent rating <b>{n(r["rating"]["per_bot"][b]["median"])}</b></p></article>' for b,c,p in zip(BOTS,COLORS,['♙','♘','♕']))
    legend=''.join(f'<span><i style="background:{c}"></i>{label(b)}</span>' for b,c in zip(BOTS,COLORS))
    months=table(['Month (UTC)','Maia 1','Maia 5','Maia 9','Total'],[(m['month'],*[n(m['per_bot'][b]) for b in BOTS],n(m['unique_games'])) for m in r['monthly_complete']])
    leaderboard=table(['Account','Rated games','Most-played Maia'],[(x['handle'],n(x['games']),label(max(x['per_bot'],key=x['per_bot'].get))) for x in r['top_accounts'][:10]])
    stats=table(['Maia','Game-weighted mean','Account-weighted mean','Middle 80%'],[(label(b),n(r['rating']['per_bot'][b]['game_mean']),n(r['rating']['per_bot'][b]['account_mean']),f"{n(r['rating']['per_bot'][b]['p10'])}–{n(r['rating']['per_bot'][b]['p90'])}") for b in BOTS])
    dotgrid=''.join(f'<i class="{"filled" if i<58 else ""}"></i>' for i in range(100))
    content=f'''<a class="skip" href="#story">Skip to report</a><header class="masthead"><a href="#" class="brand"><span aria-hidden="true">♞</span> MAIA / FIELD NOTES</a><nav aria-label="Report sections"><a href="#practice">Practice</a><a href="#community">Community</a><a href="#patterns">Play patterns</a><a href="#methods">The data</a></nav><a class="download" href="maia-fan-report.pdf">Download PDF ↗</a></header>
<main id="story"><section class="hero"><div><p class="eyebrow">A chess fan’s guide · October 2026</p><h1>One more game<br>with <em>Maia.</em></h1><p class="dek">What 1.4 million rated games reveal about the way we practice, come back, and take on a familiar chess opponent.</p><p class="hero-note">Three Maia bots. Three years of play.<br>A closer look at the habits behind the moves.</p><a class="button" href="#practice">Explore the stories <span>↓</span></a></div><div class="hero-art"><div class="board" aria-hidden="true">{''.join('<span>'+({6:'♚',28:'♟',35:'♙',36:'♙',42:'♘',62:'♔'}.get(i,''))+'</span>' for i in range(64))}</div><div class="art-caption"><b>1,425,567</b><span>collected rated games<br>Oct 2023 – Oct 2026</span></div></div></section>
<div class="scope-strip"><span class="live-dot"></span><p><b>The lens:</b> official Maia 1, 5 and 9 on Lichess. Detailed findings cover collected <b>rated games only</b>; opposing accounts are not necessarily distinct people or verified humans.</p></div>
<section class="section intro" id="practice"><div class="section-heading"><p class="eyebrow">01 / Your familiar sparring partners</p><h2>Three Maias.<br>Many ways to practice.</h2></div><div><p class="body-large">Maia 1 is the busiest of the three: {pct(r['per_bot']['maia1'],total)} of collected rated games were played against it. The higher-numbered bots attract higher-rated opponents, but all three draw a broad range of ratings.</p><p class="muted">This report looks at how accounts use Maia and whether their later results differ from their early ones. It does not measure move quality or prove that playing Maia causes improvement.</p></div><div class="bot-grid">{botcards}</div><details><summary>How opponent ratings compare</summary>{stats}<p class="small">Lichess ratings at game time, across mixed speed categories. Account-weighted means give each account equal weight within a bot; game-weighted means count frequent players more. These are not FIDE ratings or controlled comparisons.</p></details></section>
<!-- LEARNING -->
<section class="section community" id="community"><p class="eyebrow">03 / The people who keep coming back</p><h2>A small core plays<br>a lot of chess.</h2><div class="two-col"><div><div class="big-number">{accounts['top_one_percent_share']*100:.1f}<span>%</span></div><p class="body-large">of all collected games came from the busiest 1% of identified opposing accounts.</p><p>That is 930 accounts out of {n(r['opposing_accounts'])}. At the other end, {pct(accounts['one_game'],r['opposing_accounts'])} appeared in exactly one game. The median was just two.</p><p class="small">Activity in this window, not lifetime loyalty. 147 games have no opponent handle; they remain in the total-game denominator.</p></div><figure><div class="dot-grid" aria-hidden="true">{dotgrid}</div><figcaption>Each square represents roughly 1% of games.<br><span class="key-square"></span> Games played by the busiest 1% of accounts (rounded).</figcaption></figure></div><div class="fact-row"><div><b>{n(accounts['more_than_one_bot'])}</b><span>accounts tried more than one Maia</span></div><div><b>{n(accounts['all_three_bots'])}</b><span>accounts tried all three</span></div><div><b>{n(r['top_accounts'][0]['games'])}</b><span>games from the busiest account</span></div></div><!-- REMATCH --><details><summary>The ten most active public accounts</summary>{leaderboard}<p class="small">Public Lichess handles, ranked only within this rated collection. This is activity, not a ranking of improvement or playing strength.</p></details></section>
<section class="section" id="patterns"><div class="section-heading"><p class="eyebrow">04 / Coming back to the board</p><h2>Maia’s rated play<br>is on the rise.</h2></div><div class="growth-note"><strong>+{growth:.1f}%</strong><p>more games in the latest 12 complete months than in the first 12.</p></div><figure class="chart"><div class="legend">{legend}</div>{month_chart(r)}<figcaption>Monthly rated games by last recorded move · November 2023 – September 2026. May 2026 was the peak: <b>{n(r['peak_complete_month']['games'])} games</b>.</figcaption></figure><p class="small">Comparison: Nov 2023–Oct 2024 ({n(first)} games) vs Oct 2025–Sep 2026 ({n(last)}). October 2023 and October 2026 are partial and excluded. This does not establish growth in casual play.</p><details><summary>See every complete month</summary>{months}</details><div class="two-col patterns-grid"><div><p class="eyebrow">Set the clock</p><h3>Ten minutes, no increment.</h3><p>10+0 is the most common exact time control, accounting for {pct(r['top_controls'][0]['games'],total)} of games. But practice takes many forms: no single setting dominates.</p>{bars([(x['label'],x['games']) for x in r['top_controls'][:5]],total)}</div><div><p class="eyebrow">Familiar territory</p><h3>The Sicilian leads the list.</h3><p>It appears in about one in ten games. These opening families describe positions reached by both players; they are not a list of moves chosen by Maia alone.</p>{bars([(x['name'],x['games']) for x in r['opening_families'][:5]],total,'var(--gold)')}</div></div></section>
<section class="context-band"><p class="eyebrow">Zooming out / A separate all-time snapshot</p><h2>Most Maia play is casual.</h2><div class="two-col"><div><div class="big-number">{pct(a['casual_bot_entries'],a['bot_game_entries'])}</div><p>of summed all-time profile game counts were casual. The rated collection is a detailed window into Maia use, but it leaves out a large part of the story.</p></div><div class="context-stat"><b>{a['unique_games']/1e6:.2f} million</b><p>estimated distinct all-time games across the three bots, from their profile counters.</p><p class="small">Snapshot: 4 Oct 2026, 07:12 UTC. {n(a['bot_game_entries'])} summed entries minus 21 Maia-vs-Maia overlaps = {n(a['unique_games'])}. Moving counters may not synchronize exactly. Do not add this to the rated dataset.</p></div></div></section>
<section class="section methods" id="methods"><p class="eyebrow">05 / Behind the numbers</p><h2>Curiosity, with receipts.</h2><p class="body-large">Every chart starts with public game metadata. You can download the records, inspect the definitions, and rebuild the report.</p><div class="method-grid"><article><h3>What we have</h3><p>{n(total)} distinct game IDs from Maia 1, 5 and 9. Games with last recorded moves from 4 Oct 2023 00:00 UTC up to, but excluding, 4 Oct 2026 09:00 UTC. Twelve compressed CSV files contain dates, results, account handles, ratings, clocks and opening labels.</p></article><article><h3>What we don’t</h3><p>No moves, evaluations, move-by-move clocks, or casual-game history. No view of practice elsewhere. We cannot measure blunders, explain why someone returned, or attribute improvement to Maia.</p></article><article><h3>What we checked</h3><p>File hashes, row counts, unique game IDs and last-recorded-move time bounds. The collector’s date splitting was reported as complete; the public files cannot independently prove that the API omitted no games.</p></article></div><div class="data-links"><a href="https://github.com/Dash1971/researching-maia-games-on-lichess/tree/main/data/rated-games">Download the game data ↗</a><a href="data/learning_insights.json">Practice comparisons · JSON ↗</a><a href="data/fan_insights.json">Usage analyses · JSON ↗</a><a href="data/rated_summary.json">Original aggregates · JSON ↗</a><a href="https://github.com/Dash1971/researching-maia-games-on-lichess/blob/main/RESEARCH_PLAN.md">Methods & limitations ↗</a></div><details><summary>Sources, scope and reuse</summary><p>Sources: <a href="https://lichess.org/api#operation/apiGamesUser">Lichess game export</a>, <a href="https://lichess.org/api#operation/apiUser">account profiles</a>, and <a href="https://lichess.org/api#operation/apiCrosstable">bot crosstables</a>. Accounts are not verified unique people; some could be automated. No Maia-vs-Maia games appear in the rated collection. Missing opponent handles are excluded from account analyses.</p><p>The MIT license covers original code, writing and visuals, not a relicensing of Lichess or player data. See <a href="https://lichess.org/terms-of-service">Lichess terms</a>. Independent fan research, not an official Maia or Lichess publication.</p></details></section></main><footer><span class="brand">♞ MAIA / FIELD NOTES</span><p>For everyone who has ever clicked “play again.”</p><a href="#">Back to the top ↑</a></footer>'''
    content=content.replace('<!-- LEARNING -->',render_learning(insights)).replace('<!-- REMATCH -->',render_rematch(insights))
    css=(ROOT/'scripts'/'report.css').read_text()
    js=(ROOT/'scripts'/'report.js').read_text()
    payload=json.dumps(insights,ensure_ascii=False).replace('<','\\u003c')
    return '<!doctype html>\n<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="How chess fans use Maia: practice habits, repeat play and changes in results across 1.4 million rated Lichess games."><meta name="theme-color" content="#163c32"><title>One more game with Maia — Maia Field Notes</title><style>'+css+'</style></head><body>'+content+'<script type="application/json" id="insights-data">'+payload+'</script><script>'+js+'</script></body></html>\n'

def render_learning(i):
    learning=i['learning']; main,strict=learning['cohorts']; overall=main['overall']; sensitivity=strict['overall']
    panels=[]
    for key, title, row in [('all','All three Maias',overall)]+[(x['bot'],label(x['bot']),x) for x in main['by_bot']]:
        bars_html=''.join(f'<div class="score-row"><span>{text}</span><div class="score-track"><i style="width:{row[field]}%"></i></div><strong>{row[field]:.1f}%</strong></div>' for text,field in [('First 20','mean_early_score_pct'),('Last 20','mean_late_score_pct')])
        panels.append(f'<div id="scores-{key}" data-group="scores" {"hidden" if key!="all" else ""}><h3>{title} · {n(row["accounts"])} matched accounts</h3><div class="score-chart" role="img" aria-label="{title}: first 20 score {row["mean_early_score_pct"]:.1f} percent, last 20 {row["mean_late_score_pct"]:.1f} percent, full scale 0 to 100 percent">{bars_html}</div><p class="small">Full bar width = 100% score. Each account counts equally. Change: <b>{row["mean_score_change_pp"]:+.1f} percentage points</b>.</p></div>')
    buttons=''.join(f'<button type="button" data-panel="scores-{key}" aria-controls="scores-{key}" aria-pressed="{str(key=="all").lower()}">{name}</button>' for key,name in [('all','All three'),('maia1','Maia 1'),('maia5','Maia 5'),('maia9','Maia 9')])
    distribution=''.join(f'<span style="width:{row/overall["accounts"]*100}%;background:{c}">{pct(row,overall["accounts"])}</span>' for row,c in [(overall['improved_accounts'],'#b7e281'),(overall['unchanged_accounts'],'#d6ddc9'),(overall['declined_accounts'],'#e8b96b')])
    bybot=table(['Maia','Accounts','First 20 score','Last 20 score','Change'],[(label(x['bot']),n(x['accounts']),f'{x["mean_early_score_pct"]:.1f}%',f'{x["mean_late_score_pct"]:.1f}%',f'{x["mean_score_change_pp"]:+.1f} pp') for x in main['by_bot']])
    stricttable=table(['Maia','Accounts','Score change'],[(label(x['bot']),n(x['accounts']),f'{x["mean_score_change_pp"]:+.1f} pp') for x in strict['by_bot']])
    results=table(['Opponent facing','Win','Draw','Loss','Unclassified'],[(label(x['bot']),pct(x['win'],x['games']),pct(x['draw'],x['games']),pct(x['loss'],x['games']),pct(x['unknown'],x['games'])) for x in i['outcomes_by_bot']])
    return f'''<section class="section learning" id="learning"><p class="eyebrow">02 / Practice & progress</p><h2>Later results are a little better.<br>But the story is mixed.</h2><p class="body-large">Among {n(overall['accounts'])} persistent accounts, average score rose from {overall['mean_early_score_pct']:.1f}% in their first 20 games to {overall['mean_late_score_pct']:.1f}% in their last 20 against a matched Maia opponent. That is a modest <b>{overall['mean_score_change_pp']:.1f}-point increase</b>.</p><div class="two-col"><div><div class="filter" data-filter-group="scores" role="group" aria-label="Select Maia for early versus later scores">{buttons}</div>{''.join(panels)}<p class="small"><b>Score</b> means wins plus half a point per draw, divided by games. A 50% score is half the available points, not necessarily a 50% win rate.</p></div><div><h3>How we made the comparison</h3><p>Same account. Same Maia. Same exact clock and speed category. At least 40 usable games, with at least 30 days between the early and later groups. One qualifying combination per account; each account gets equal weight.</p><p class="small">“First” and “last” mean observed in this collection, not their first-ever or final Maia games. These accounts are a small, selected subset of the 93,020 observed accounts.</p></div></div><h3>More accounts scored better, but many scored worse.</h3><div class="distribution" aria-hidden="true">{distribution}</div><div class="result-grid"><div><b>{n(overall['improved_accounts'])}</b><span>higher later score · {pct(overall['improved_accounts'],overall['accounts'])}</span></div><div><b>{n(overall['unchanged_accounts'])}</b><span>unchanged score · {pct(overall['unchanged_accounts'],overall['accounts'])}</span></div><div><b>{n(overall['declined_accounts'])}</b><span>lower later score · {pct(overall['declined_accounts'],overall['accounts'])}</span></div></div><div class="callout"><b>The Maia detail matters.</b> The average rise is clearest against Maia 1 (+4.0 points). Against Maia 9 it is only +0.3 points, and turns negative in the stricter comparison. The data do not support a uniform improvement story across all three bots.</div>{bybot}<p class="small"><b>Stricter check:</b> requiring 60 games and a 90-day gap leaves {n(sensitivity['accounts'])} accounts. Their average score rises {sensitivity['mean_score_change_pp']:.1f} points. This is an overlapping subset, not an independent replication. Twenty-game scores are noisy; “higher” is not a test of statistically reliable individual improvement.</p><details><summary>Stricter results and the limits of this comparison</summary>{stricttable}<p>The most-played eligible Maia/clock/speed combination is selected once per account, independently for each comparison. Games with unknown outcomes or cheat terminations are excluded. Chronological ordering uses game start time; ties use game ID.</p><p>In the main group, mean recorded opponent rating rose {overall['mean_opponent_rating_change']:.1f} points, while Maia’s recorded rating rose {overall['mean_bot_rating_change']:.1f}. Accounts had White in {overall['mean_early_white_pct']:.1f}% of early games and {overall['mean_late_white_pct']:.1f}% of later games. These diagnostics do not fully control for bot changes or color.</p><p>People who return may differ from those who stop. Other chess practice, regression to the mean, changing bot strength, and ordinary luck can affect results. There is no comparison group and no move-quality analysis, so this is an association with repeated play, not a measured training effect.</p><a href="data/learning_insights.json">Download all matched comparisons and definitions ↗</a></details><div class="outcomes"><h3>Maia gives opponents a real contest.</h3><p>Across the full collection, opposing accounts won about four games in ten against each bot. Maia 9’s visitors are generally higher rated; similar win rates do not mean the bots are equally strong.</p>{results}<p class="small">Opponent perspective; denominator is all games against that bot. Blank winners are classified as draws only for explicit draw/stalemate endings. Other no-winner endings remain unclassified. These are recorded outcomes, including 110 cheat terminations in the full dataset.</p></div><p class="callout"><b>What a Maia fan can take away:</b> some returning accounts show better later results against a familiar bot, especially Maia 1. People who keep playing are a selected group and can practice elsewhere. This comparison cannot show that Maia caused the gains.</p></section>'''

def render_rematch(i):
    rows=i['quick_returns_by_bot_and_prior_outcome']
    data={(x['bot'],x['previous_opponent_outcome']):x for x in rows}
    chart=''
    for b in BOTS:
        chart+=f'<div><h4>{label(b)}</h4>'
        for outcome,word,c in [('win','After a win','#8caa70'),('loss','After a loss','#244e3d')]:
            x=data[(b,outcome)]
            chart+=f'<div class="score-row"><span>{word}</span><div class="score-track"><i style="width:{x["same_maia_pct"]}%;background:{c}"></i></div><strong>{x["same_maia_pct"]:.1f}%</strong></div>'
        chart+='</div>'
    counts=table(['Maia','After result','Eligible games','Quick same-Maia returns'],[(label(b),o,n(data[(b,o)]['eligible_games']),n(data[(b,o)]['quick_return_same_maia'])) for b in BOTS for o in ('win','loss')])
    return f'''<div class="rematch"><p class="eyebrow">The “one more game” pattern</p><h3>A loss is more often followed by a quick return.</h3><p>For every Maia, a quick return to the same bot was more common after a loss than after a win. Against Maia 1, the rates were 53.5% after losses and 43.2% after wins.</p><div class="rematch-chart">{chart}</div><p class="small">Share of eligible games followed by the same account’s next observed Maia rated game against the same bot within 10 minutes of the previous last recorded move. Full bar width = 100%. This does not identify a formal rematch or tell us why the account returned.</p><details><summary>Return counts and what we cannot see</summary>{counts}<p class="small">Only identified accounts and prior games with at least ten minutes remaining before the dataset boundary are eligible. Negative gaps are excluded from the return numerator. The prior last move can precede resignation or flagging. Casual games, non-Maia opponents and games ending outside the dataset are unobserved. Frequent accounts count more; clocks, ratings and individual habits differ.</p></details></div>'''
